def optimize_skinbindings(out, replace):
    path = out / 'managed/SharpGLTF/DrawableTemplate.cs'
    text = path.read_text()
    text = replace(text, 'public override Transforms.IGeometryTransform CreateGeometryTransform() { return new Transforms.SkinnedTransform(); }', '// Each drawable owns its callbacks. Keep only a temporary armature\n        // reference during synchronous Update, not a captured per-access closure.\n        private sealed class BoundSkinTransform : Transforms.SkinnedTransform\n        {\n            private readonly Func<int, Matrix4x4> inverseBind, world;\n            internal readonly Matrix4x4[] Bindings;\n            private readonly int[] joints;\n            private ArmatureInstance currentArmature;\n            private readonly int count;\n            public BoundSkinTransform(Matrix4x4[] bindings, int[] joints)\n            {\n                count = joints.Length;\n                Bindings = bindings;\n                this.joints = joints;\n                inverseBind = ReadInverseBind;\n                world = ReadWorld;\n            }\n            private Matrix4x4 ReadInverseBind(int index) => Bindings[index];\n            private Matrix4x4 ReadWorld(int index) => currentArmature.LogicalNodes[joints[index]].ModelMatrix;\n            public void UpdateFrom(ArmatureInstance armature)\n            {\n                currentArmature = armature;\n                try { Update(count, inverseBind, world); }\n                finally { currentArmature = null; }\n            }\n        }\n\n        public override Transforms.IGeometryTransform CreateGeometryTransform()\n        { return new BoundSkinTransform(_BindMatrices, _JointsNodeIndices); }\n\n        private void UpdateUnbound(Transforms.SkinnedTransform transform, ArmatureInstance armature)\n        {\n            transform.Update(_JointsNodeIndices.Length, index => _BindMatrices[index],\n                index => armature.LogicalNodes[_JointsNodeIndices[index]].ModelMatrix);\n        }')
    text = replace(text, 'skinxform.Update(_JointsNodeIndices.Length, idx => _BindMatrices[idx], idx => armature.LogicalNodes[_JointsNodeIndices[idx]].ModelMatrix);', 'if (skinxform is BoundSkinTransform bound && bound.Bindings == _BindMatrices)\n                bound.UpdateFrom(armature);\n            else\n                UpdateUnbound(skinxform, armature);')
    path.write_text(text)
